+// Sites (kitchens). Every location belongs to one site; a batch belongs to
+// the site of its location. Items, suppliers, recipes and dishes are shared
+// by all sites. Functions that take `site` see every site when it is omitted.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site a location belongs to (locations not on the list count as the default site). */
+export function siteOfLocation(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site ?? DEFAULT_SITE;
+}
+
+/** Whether a location id is on the list and, when `site` is given, belongs to it. */
+export function isLocationAt(store, locationId, site) {
+  const loc = store.data.locations.find((l) => l.id === locationId);
+  return Boolean(loc) && (site === undefined || loc.site === site);
+}
+
+/** Whether a batch is visible at `site` (always true when `site` is omitted). */
+export function batchAt(store, batch, site) {
+  return site === undefined || siteOfLocation(store, batch.location) === site;
+}
