@@ -0,0 +1,105 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, NOW } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+// Puts one batch of item 2 (milk) into the annex fridge.
+function stockAnnex(store) {
+  store.data.batches.push({ id: store.nextId("batch"), itemId: 2, lot: "AX-1", qty: 4, receivedOn: "2026-10-27", expires: "2026-10-29", location: "annex-fridge" });
+  return store.data.seq.batch;
+}
+
+test("the seed has two sites and every location has one", async () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites, [{ id: "main", name: "Main kitchen" }, { id: "annex", name: "Annex kitchen" }]);
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+  assert.ok(store.data.locations.every((l) => l.site));
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("without the header the site is main", async () => {
+  const { handle } = app();
+  const a = await handle({ path: "/items" });
+  const b = await handle({ path: "/items", headers: { "X-Larder-Site": "main" } });
+  assert.deepEqual(a.body, b.body);
+  assert.equal(a.body.find((i) => i.id === 1).onHand, 10);
+});
+
+test("stock, batches and the stock value only see the request's site", async () => {
+  const { handle, store } = app();
+  const id = stockAnnex(store);
+  const items = (await handle({ path: "/items", headers: annex })).body;
+  assert.equal(items.length, 6);
+  assert.equal(items.find((i) => i.id === 2).onHand, 4);
+  assert.equal(items.find((i) => i.id === 1).onHand, 0);
+  assert.equal((await handle({ path: "/items" })).body.find((i) => i.id === 2).onHand, 10);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body.map((b) => b.id), [id]);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: `/batches/${id}` })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: annex, body: { qty: 1 } })).status, 404);
+  const value = (await handle({ path: "/reports/stock-value", headers: annex })).body;
+  assert.equal(value.totalCents, 4 * 129);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("alerts only see the request's site", async () => {
+  const { handle, store } = app();
+  stockAnnex(store);
+  const a = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(a.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(a.lowStock.some((l) => l.itemId === 1));
+  const m = (await handle({ path: "/alerts" })).body;
+  assert.ok(!m.expiring.some((b) => b.lot === "AX-1"));
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle, store } = app();
+  const id = stockAnnex(store);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } })).body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: id, counted: 3 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: id, counted: 3 } })).status, 200);
+  const res = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex });
+  assert.deepEqual(res.body.lines, [{ batchId: id, expected: 4, counted: 3, diff: -1 }]);
+});
+
+test("orders are received into the request's site", async () => {
+  const { handle } = app();
+  const bad = await handle({ method: "POST", path: "/orders/2/receive", headers: annex, body: { lots: [{ lot: "a", location: "fridge" }, { lot: "b", location: "fridge" }] } });
+  assert.equal(bad.body.error.code, "unknown_location");
+  const ok = await handle({ method: "POST", path: "/orders/2/receive", headers: annex, body: { lots: [{ lot: "a", location: "annex-fridge" }, { lot: "b", location: "annex-fridge" }] } });
+  assert.equal(ok.status, 200);
+  assert.equal((await handle({ path: "/items/2", headers: annex })).body.onHand, 12);
+});
+
+test("shared data is the same at every site", async () => {
+  const { handle } = app();
+  for (const path of ["/suppliers", "/dishes", "/recipes/1/cost"])
+    assert.deepEqual((await handle({ path, headers: annex })).body, (await handle({ path })).body);
+});
+
+test("the nightly job checks low stock per site, safely twice", async () => {
+  const { handle, store } = app();
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const keys = store.data.outbox.map((m) => m.key);
+  assert.ok(!keys.includes("low:2026-10-28"));
+  assert.ok(keys.includes("low:annex:2026-10-28"));
+  await handle({ method: "POST", path: "/jobs/nightly", headers: annex });
+  assert.equal(store.data.outbox.length, keys.length);
+  assert.equal(NOW > 0, true);
+});
